using System.ComponentModel.DataAnnotations;
namespace Tamayoz.Models;
public class ServiceRequest { public int Id { get; set; } public int ServiceId { get; set; } public Service? Service { get; set; } [Required, StringLength(120)] public string StudentName { get; set; } = string.Empty; [Required, EmailAddress, StringLength(160)] public string StudentEmail { get; set; } = string.Empty; [Required, Phone, StringLength(30)] public string StudentPhone { get; set; } = string.Empty; [Required, StringLength(2000)] public string Message { get; set; } = string.Empty; [StringLength(40)] public string? PreferredContactMethod { get; set; } public RequestStatus Status { get; set; } = RequestStatus.Pending; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime? UpdatedAt { get; set; } }
